import{_ as a,C as t,c as r,o as d,j as s,G as o,ak as n,a as l}from"./chunks/framework.14-H7uoj.js";const c="/img/svg/408_DS/set-structure.svg",p="/img/svg/408_DS/linear-structure.svg",g="/img/svg/408_DS/tree-structure.svg",m="/img/svg/408_DS/graph-structure.svg",v="/img/svg/408_DS/storage-overview.svg",u="/img/svg/408_DS/sequential-storage.svg",f="/img/svg/408_DS/linked-storage.svg",b="/img/svg/408_DS/indexed-storage.svg",y="/img/svg/408_DS/hash-storage.svg",h="/img/svg/408_DS/operation-definition.svg",_="/img/svg/408_DS/operation-implementation.svg",T=JSON.parse('{"title":"数据结构三要素","titleTemplate":"408数据结构","description":"数据结构三要素","frontmatter":{"title":"数据结构三要素","titleTemplate":"408数据结构","description":"数据结构三要素","layout":"doc","navbar":true,"sidebar":true,"aside":true,"outline":"deep","lastUpdated":true,"prev":false,"next":false},"headers":[],"relativePath":"post/kaoyan/408/408_DS/01/408_DS_2.md","filePath":"post/kaoyan/408/408_DS/01/408_DS_2.md","lastUpdated":1756123810000}'),x={name:"post/kaoyan/408/408_DS/01/408_DS_2.md"};function k(S,e,z,w,D,q){const i=t("ArticleSummary");return d(),r("div",null,[e[0]||(e[0]=s("h1",{id:"数据结构三要素",tabindex:"-1"},[l("数据结构三要素 "),s("a",{class:"header-anchor",href:"#数据结构三要素","aria-label":'Permalink to "数据结构三要素"'},"​")],-1)),o(i,{texts:["深度解析数据结构的核心本质：逻辑结构 + 存储结构 + 数据运算。从集合的无序独立到图状的多对多关系，从顺序存储的连续空间到散列存储的快速定位，全面构建数据结构的理论基础和实践应用体系。（内容由 AI 生成，仅供参考）","掌握数据结构三要素，开启算法设计之门！本文系统阐述四种逻辑结构（集合、线性、树形、图状）的关系特征，四种存储方式（顺序、链式、索引、散列）的实现原理，以及运算定义与实现的本质区别。（内容由 AI 生成，仅供参考）","从抽象逻辑到物理存储，从运算定义到具体实现！本文通过丰富的可视化图表，深入浅出地讲解数据结构三要素的内在联系，揭示逻辑结构如何映射到存储结构，运算如何在不同存储方式下实现。（内容由 AI 生成，仅供参考）","数据结构 = 逻辑关系的抽象 + 物理存储的实现 + 操作方法的定义！本文为408考研学子量身打造，涵盖一对一线性关系、一对多树形关系、多对多图状关系，以及随机存取、动态分配、快速检索等核心概念。（内容由 AI 生成，仅供参考）"]}),e[1]||(e[1]=n('<h2 id="数据的逻辑结构" tabindex="-1">数据的逻辑结构 <a class="header-anchor" href="#数据的逻辑结构" aria-label="Permalink to &quot;数据的逻辑结构&quot;">​</a></h2><p><span class="blue-b">逻辑结构</span>是指<span class="blue">数据元素之间的逻辑关系</span>，即从逻辑关系上描述数据。它与数据的存储无关，是独立于计算机的。数据的逻辑结构分为 <span class="blue-m">线性结构</span> 和 <span class="blue-m">非线性结构</span> ，<strong>线性表</strong>是典型的线性结构；<strong>集合、树和图</strong>是典型的非线性结构。</p><div class="card-container"><div class="logic-structure-card set"><div class="mb-4"><img src="'+c+'" alt="集合结构" class="logic-structure-icon"></div><div class="logic-structure-title set">集合结构</div><div class="logic-structure-desc set">数据元素之间仅 &quot;同属一个集合&quot;</div><div class="logic-structure-tag set">无序、独立</div></div><div class="logic-structure-card linear"><div class="mb-4"><img src="'+p+'" alt="线性结构" class="logic-structure-icon"></div><div class="logic-structure-title linear">线性结构</div><div class="logic-structure-desc linear">数据元素之间只存在一对一的关系</div><div class="logic-structure-tag linear">一对一</div></div><div class="logic-structure-card tree"><div class="mb-4"><img src="'+g+'" alt="树形结构" class="logic-structure-icon"></div><div class="logic-structure-title tree">树形结构</div><div class="logic-structure-desc tree">数据元素之间存在一对多的关系</div><div class="logic-structure-tag tree">一对多</div></div><div class="logic-structure-card graph"><div class="mb-4"><img src="'+m+'" alt="图状结构" class="logic-structure-icon"></div><div class="logic-structure-title graph">图状结构</div><div class="logic-structure-desc graph">数据元素之间存在多对多的关系</div><div class="logic-structure-tag graph">多对多</div></div></div><div class="xuxianfg"></div><h2 id="数据的存储结构" tabindex="-1">数据的存储结构 <a class="header-anchor" href="#数据的存储结构" aria-label="Permalink to &quot;数据的存储结构&quot;">​</a></h2><p><span class="blue-b">存储结构</span>是指<span class="blue">数据结构在计算机中的表示</span>（也称映像），也称 <span class="blue-m">物理结构</span> 。</p><div class="flex-center" style="margin:2rem 0;"><div class="storage-card"><div class="mb-6"><img src="'+v+'" alt="存储结构概览" class="storage-card-icon"></div><div class="storage-card-title">存储结构 = 数据表示 + 关系表示</div><div class="storage-card-desc mt-2">逻辑结构在计算机中的物理实现</div></div></div><p>它包括 <span class="blue-m">数据元素的表示</span> 和 <span class="blue-m">关系的表示</span> 。数据的存储结构是用计算机语言实现的逻辑结构，它依赖于计算机语言。</p><p>数据的存储结构主要有：<span class="blue-b">顺序存储</span>、<span class="blue-b">链式存储</span>、<span class="blue-b">索引存储</span>和<span class="blue-b">散列存储</span>。</p><div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(300px, 1fr));gap:1.5rem;margin:2rem 0;"><div style="background:linear-gradient(135deg, #e0f2fe 0%, #bae6fd 100%);border-radius:25px;padding:1.5rem;"><div style="display:flex;align-items:center;margin-bottom:1rem;"><img src="'+u+'" alt="顺序存储" style="width:40px;height:40px;margin-right:0.8rem;"><div><div style="font-weight:600;color:#0c4a6e;font-size:1.1rem;">顺序存储</div><div style="font-size:0.8rem;color:#0c4a6e;">Sequential Storage</div></div></div><div style="font-size:0.9rem;color:#0c4a6e;margin-bottom:1rem;line-height:1.5;">把逻辑上相邻的元素存储在物理位置上也相邻的存储单元中，元素之间的关系由存储单元的邻接关系来体现。</div><div style="display:flex;gap:0.5rem;margin-bottom:0.8rem;"><span style="background:#dcfce7;color:#16a34a;padding:0.2rem 0.5rem;border-radius:8px;font-size:0.8rem;font-weight:500;">✓ 随机存取</span><span style="background:#dcfce7;color:#16a34a;padding:0.2rem 0.5rem;border-radius:8px;font-size:0.8rem;font-weight:500;">✓ 空间利用率高</span></div><div style="display:flex;gap:0.5rem;"><span style="background:#fee2e2;color:#dc2626;padding:0.2rem 0.5rem;border-radius:8px;font-size:0.8rem;font-weight:500;">✗ 插入删除困难</span><span style="background:#fee2e2;color:#dc2626;padding:0.2rem 0.5rem;border-radius:8px;font-size:0.8rem;font-weight:500;">✗ 可能产生碎片</span></div></div><div style="background:linear-gradient(135deg, #dcfce7 0%, #bbf7d0 100%);border-radius:25px;padding:1.5rem;"><div style="display:flex;align-items:center;margin-bottom:1rem;"><img src="'+f+'" alt="链式存储" style="width:40px;height:40px;margin-right:0.8rem;"><div><div style="font-weight:600;color:#14532d;font-size:1.1rem;">链式存储</div><div style="font-size:0.8rem;color:#14532d;">Linked Storage</div></div></div><div style="font-size:0.9rem;color:#14532d;margin-bottom:1rem;line-height:1.5;">不要求逻辑上相邻的元素在物理位置上也相邻，借助指示元素存储地址的指针来表示元素之间的逻辑关系。</div><div style="display:flex;gap:0.5rem;margin-bottom:0.8rem;"><span style="background:#dcfce7;color:#16a34a;padding:0.2rem 0.5rem;border-radius:8px;font-size:0.8rem;font-weight:500;">✓ 插入删除方便</span><span style="background:#dcfce7;color:#16a34a;padding:0.2rem 0.5rem;border-radius:8px;font-size:0.8rem;font-weight:500;">✓ 无碎片</span></div><div style="display:flex;gap:0.5rem;"><span style="background:#fee2e2;color:#dc2626;padding:0.2rem 0.5rem;border-radius:8px;font-size:0.8rem;font-weight:500;">✗ 额外指针空间</span><span style="background:#fee2e2;color:#dc2626;padding:0.2rem 0.5rem;border-radius:8px;font-size:0.8rem;font-weight:500;">✗ 顺序存取</span></div></div><div style="background:linear-gradient(135deg, #fef3c7 0%, #fde68a 100%);border-radius:25px;padding:1.5rem;"><div style="display:flex;align-items:center;margin-bottom:1rem;"><img src="'+b+'" alt="索引存储" style="width:40px;height:40px;margin-right:0.8rem;"><div><div style="font-weight:600;color:#92400e;font-size:1.1rem;">索引存储</div><div style="font-size:0.8rem;color:#92400e;">Indexed Storage</div></div></div><div style="font-size:0.9rem;color:#92400e;margin-bottom:1rem;line-height:1.5;">在存储元素信息的同时，还建立附加的索引表。索引表中的每项称为索引项，索引项的一般形式是（关键字，地址）。</div><div style="display:flex;gap:0.5rem;margin-bottom:0.8rem;"><span style="background:#dcfce7;color:#16a34a;padding:0.2rem 0.5rem;border-radius:8px;font-size:0.8rem;font-weight:500;">✓ 检索速度快</span></div><div style="display:flex;gap:0.5rem;"><span style="background:#fee2e2;color:#dc2626;padding:0.2rem 0.5rem;border-radius:8px;font-size:0.8rem;font-weight:500;">✗ 额外索引空间</span><span style="background:#fee2e2;color:#dc2626;padding:0.2rem 0.5rem;border-radius:8px;font-size:0.8rem;font-weight:500;">✗ 维护索引开销</span></div></div><div style="background:linear-gradient(135deg, #fce7f3 0%, #fbcfe8 100%);border-radius:25px;padding:1.5rem;"><div style="display:flex;align-items:center;margin-bottom:1rem;"><img src="'+y+'" alt="散列存储" style="width:40px;height:40px;margin-right:0.8rem;"><div><div style="font-weight:600;color:#9d174d;font-size:1.1rem;">散列存储</div><div style="font-size:0.8rem;color:#9d174d;">Hash Storage</div></div></div><div style="font-size:0.9rem;color:#9d174d;margin-bottom:1rem;line-height:1.5;">根据元素的关键字直接计算出该元素的存储地址，<br>也称哈希（Hash）存储。</div><div style="display:flex;gap:0.5rem;margin-bottom:0.8rem;"><span style="background:#dcfce7;color:#16a34a;padding:0.2rem 0.5rem;border-radius:8px;font-size:0.8rem;font-weight:500;">✓ 操作速度快</span></div><div style="display:flex;gap:0.5rem;"><span style="background:#fee2e2;color:#dc2626;padding:0.2rem 0.5rem;border-radius:8px;font-size:0.8rem;font-weight:500;">✗ 可能冲突</span><span style="background:#fee2e2;color:#dc2626;padding:0.2rem 0.5rem;border-radius:8px;font-size:0.8rem;font-weight:500;">✗ 解决冲突开销</span></div></div></div><div class="xuxianfg"></div><h2 id="数据的运算" tabindex="-1">数据的运算 <a class="header-anchor" href="#数据的运算" aria-label="Permalink to &quot;数据的运算&quot;">​</a></h2><p><span class="blue-b">施加在数据上的运算</span>包括 <span class="blue-m">运算的定义</span> 和 <span class="blue-m">实现</span> 。运算的定义是针对逻辑结构的，指出运算的功能；运算的实现是针对存储结构的，指出运算的具体操作步骤。</p><div class="operation-container"><div class="operation-types"><div class="operation-type"><div class="operation-type-card definition"><img src="'+h+'" alt="运算定义" class="operation-type-icon"><div class="operation-type-title definition">运算定义</div><div class="operation-type-subtitle definition">针对逻辑结构</div></div><div class="operation-type-desc">指出运算的 <span class="blue-m">功能</span></div></div><div class="operation-type"><div class="operation-type-card implementation"><img src="'+_+'" alt="运算实现" class="operation-type-icon"><div class="operation-type-title implementation">运算实现</div><div class="operation-type-subtitle implementation">针对存储结构</div></div><div class="operation-type-desc">指出运算的 <span class="blue-m">步骤</span></div></div></div><div class="operation-list"><div class="operation-list-title">常见数据运算</div><div class="operation-tags"><div class="operation-tag insert">插入</div><div class="operation-tag delete">删除</div><div class="operation-tag search">查找</div><div class="operation-tag update">更新</div><div class="operation-tag traverse">遍历</div><div class="operation-tag sort">排序</div></div></div></div><blockquote><p>数据的<span class="blue">逻辑结构</span>和<span class="blue">存储结构</span>是密不可分的两个方面，一个算法的设计取决于所选定的逻辑结构，而算法的实现依赖于所采用的存储结构。</p></blockquote>',15))])}const P=a(x,[["render",k]]);export{T as __pageData,P as default};
